// Construct a concrete Decoder implementation since Decoder is abstract.
// We define a local class implementing all pure virtuals. No global state or threads are used.
class FuzzDecoder final : public Decoder {
public:
    // Simple lifecycle state model
    enum class State { kInit, kStarted, kPaused, kStopped };

    // Stored callback
    void* cb_ctx_ = nullptr;
    MessageCallback cb_ = nullptr;

    // Media properties
    float duration_ = 0.0f;      // non-negative, finite
    float position_ = 0.0f;      // in [0, duration_]
    State state_ = State::kInit;

    // Helper: optionally notify via callback (synchronous and minimal)
    void Notify(int code, float value) {
        if (cb_) { cb_(cb_ctx_, code, value); }
    }

    // Decoder interface
    void Start() override {
        // Transition to started; position unchanged
        state_ = State::kStarted;
        // Notify with a lightweight event code 1
        Notify(1, position_);
    }
    void Pause() override {
        state_ = State::kPaused;
        // Notify with code 2
        Notify(2, position_);
    }
    void Stop() override {
        state_ = State::kStopped;
        // Notify with code 3
        Notify(3, position_);
    }
    float GetDuration() override {
        return duration_;
    }
    void SeekToPosition(float position) override {
        // Clamp to [0, duration_]; duration_ is guaranteed non-negative and finite
        if (position < 0.0f) position = 0.0f;
        if (position > duration_) position = duration_;
        position_ = position;
        // Notify with code 4 and the new position
        Notify(4, position_);
    }
    float GetCurrentPosition() override {
        return position_;
    }
    void SetMessageCallback(void* context, MessageCallback callback) override {
        cb_ctx_ = context;
        cb_ = callback;
        // Notify with code 5 to indicate registration (only if non-null)
        Notify(5, position_);
    }
};

// Choose a duration from fuzz data; sanitize to a reasonable, finite, non-negative value.
float raw_dur = *FUZZ_PARAM(float);
// Avoid NaN/Inf and negatives; cap to a small upper bound for safety/perf.
float duration = (raw_dur == raw_dur && raw_dur > 0.0f) ? raw_dur : 60.0f; // default 60s if invalid
if (duration > 3600.0f) duration = 3600.0f; // cap at 1 hour

// Create the concrete decoder and initialize fields.
FuzzDecoder* impl = new FuzzDecoder();
impl->duration_ = duration;
impl->position_ = 0.0f;
impl->state_ = FuzzDecoder::State::kInit;

// Expose as the abstract interface pointer.
Decoder* decoder = static_cast<Decoder*>(impl);

// Tag attributes for downstream stubs to know this is a concrete, usable instance.
